/// What each bake is published as, read by the client for the path it
/// requests: `v<format>.<release>`, the format the bake was written in and
/// the Overture release it was baked from, as the ingest catalog names it.
///
/// A published folder is immutable, so a cache never holds a page another
/// replaced and going back is naming the folder before. A new release is a
/// new folder under the same format; a change to what a page holds or how it
/// is baked bumps the format. Setting a name here is the whole change.
pub struct PublishedVersion {
    pub terrain: &'static str,
    pub poi: &'static str,
    pub geocode: &'static str,
}

pub const PUBLISHED_VERSION: PublishedVersion = PublishedVersion {
    terrain: "v7.2026-09-23.1",
    poi: "v9.2026-09-23.1",
    geocode: "v5.2026-09-23.1",
};

/// The format each bake writes now, which a bake's folder is named by with
/// its release. Bumped by a change to what a page holds or how it is baked.
pub struct Format {
    pub terrain: u32,
    pub poi: u32,
    pub geocode: u32,
}

pub const FORMAT: Format = Format { terrain: 7, poi: 9, geocode: 5 };

/// A bake's folder and published name: its format and the release it was baked from.
pub fn version_name(format: u32, release: &str) -> String {
    format!("v{format}.{release}")
}

/// The kinds a version is published for: the fields of `PUBLISHED_VERSION`,
/// numbered in their order.
#[allow(non_camel_case_types)]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u32)]
pub enum BakeKind {
    terrain,
    poi,
    geocode,
}

impl BakeKind {
    pub const ALL: [BakeKind; 3] = [BakeKind::terrain, BakeKind::poi, BakeKind::geocode];

    /// The kind a number names, or none for a number nobody gave out.
    pub fn of(number: u32) -> Option<BakeKind> {
        BakeKind::ALL.into_iter().find(|k| *k as u32 == number)
    }
}

impl PublishedVersion {
    /// `PUBLISHED_VERSION[kind]`.
    pub fn of(&self, kind: BakeKind) -> &'static str {
        match kind {
            BakeKind::terrain => self.terrain,
            BakeKind::poi => self.poi,
            BakeKind::geocode => self.geocode,
        }
    }
}

/// What the published bake declares of itself to the client: `top_level`, the
